/* @autogenerated */
import { Component, signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { of } from 'rxjs';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { AppStateService, ContextValue, GLOBAL_CONTEXT } from '@shared/context/state/app-state.service';
import { selectorProvider } from '@shared/data/selector-provider';
import { APP_CONFIG } from '@shared/context/config/app-config.service';
import { emptyConfig } from '@shared/context/config/app-config.model';
import { ContextSelectorComponent } from './context-selector.component';
import { EditableSelectoneComponent } from '../editable/editable-selectone/editable-selectone.component';

const STORED = 'state-item-contexts';

const provider = selectorProvider<any, any>({
  search: () => of([]),
  display: (item) => item.name,
  value: (item) => ({ $ref: item.uid }),
  select: (value) => of({ uid: value.$ref, name: `item-${value.$ref}` }),
  equals: (a, b) => a?.$ref === b?.$ref,
});

@Component({
  imports: [ContextSelectorComponent],
  template: `
    <context-selector key="client" entity="client" [provider]="provider" [global]="global()" />
    <context-selector key="site" entity="site" [requires]="['client']" [provider]="provider" mode="filter" />
  `,
})
class HostComponent {
  provider = provider;
  global = signal(false);
}

describe('ContextSelectorComponent', () => {
  let fixture: ComponentFixture<HostComponent>;
  let state: AppStateService;

  beforeEach(() => {
    localStorage.removeItem(STORED);
    TestBed.configureTestingModule({
      providers: [{ provide: APP_CONFIG, useValue: signal(emptyConfig('test')) }],
      imports: [
        HostComponent,
        TranslocoTestingModule.forRoot({ langs: {}, translocoConfig: { availableLangs: ['es'], defaultLang: 'es' } }),
      ],
    });
    state = TestBed.inject(AppStateService);
    state.contextScope.set('admin');
    fixture = TestBed.createComponent(HostComponent);
    fixture.detectChanges();
  });

  afterEach(() => localStorage.removeItem(STORED));

  function selectors(): ContextSelectorComponent[] {
    return fixture.debugElement
      .queryAll((node) => node.componentInstance instanceof ContextSelectorComponent)
      .map((node) => node.componentInstance);
  }

  it('stores the choice with its entity in the active workspace', () => {
    selectors()[0].control.setValue({ $ref: 'c1' });

    const entry = state.contexts()['client'];
    expect(entry?.value).toEqual({ $ref: 'c1' });
    expect(entry?.entity).toBe('client');
    expect(entry?.toFilter).toBeTrue();
    state.contextScope.set('main');
    expect(state.contexts()['client']).toBeUndefined();
  });

  it('shares the choice with every workspace when global', () => {
    fixture.componentInstance.global.set(true);
    fixture.detectChanges();
    selectors()[0].control.setValue({ $ref: 'c1' });

    state.contextScope.set('main');
    expect(state.contexts()['client']?.value).toEqual({ $ref: 'c1' });
    expect(state.contextValue('client')()).toBeTruthy();
    expect(GLOBAL_CONTEXT).toBe('*');
  });

  it('shows a dependent selector disabled until its requirements have a value, and empties it without them', () => {
    const [client, site] = selectors();
    const select = spyOn(provider, 'select').and.callThrough();
    expect(fixture.nativeElement.querySelectorAll('editable-selectone').length).toBe(2);
    expect(site.enabled()).toBeFalse();
    expect(site.control.disabled).toBeTrue();
    expect(fixture.nativeElement.querySelectorAll('editable-selectone button[matSuffix]').length).toBe(1);
    const siteInput = fixture.debugElement.queryAll(
      (node) => node.componentInstance instanceof EditableSelectoneComponent,
    )[1].componentInstance as EditableSelectoneComponent<any, any>;

    client.control.setValue({ $ref: 'c1' });
    fixture.detectChanges();
    expect(site.enabled()).toBeTrue();
    expect(site.control.enabled).toBeTrue();
    expect(fixture.nativeElement.querySelectorAll('editable-selectone button[matSuffix]').length).toBe(2);

    site.control.setValue({ $ref: 's1' });
    provider.select({ $ref: 's1' });
    expect(state.contexts()['site']?.toFilter).toBeTrue();
    expect(state.contexts()['site']?.fixed).toBeFalse();

    client.control.setValue(null);
    fixture.detectChanges();
    expect(state.contexts()['client']).toBeNull();
    expect(state.contexts()['site']).toBeNull();
    expect(site.control.disabled).toBeTrue();
    expect(site.control.value).toBeNull();
    expect(select).toHaveBeenCalledWith(null);
  });

  it('empties a dependent selector when its parent changes to another value', () => {
    const [client, site] = selectors();
    const select = spyOn(provider, 'select').and.callThrough();
    client.control.setValue({ $ref: 'c1' });
    fixture.detectChanges();
    site.control.setValue({ $ref: 's1' });
    fixture.detectChanges();
    expect(state.contexts()['site']?.value).toEqual({ $ref: 's1' });

    // Reemitir el mismo padre no borra nada
    client.control.setValue({ $ref: 'c1', $id: 'x' });
    fixture.detectChanges();
    expect(state.contexts()['site']?.value).toEqual({ $ref: 's1' });

    provider.select({ $ref: 's1' });
    client.control.setValue({ $ref: 'c2' });
    fixture.detectChanges();
    expect(state.contexts()['site']).toBeNull();
    expect(site.control.value).toBeNull();
    expect(select).toHaveBeenCalledWith(null);
    expect(site.control.enabled).toBeTrue();
  });

  it('keeps the choices of each workspace when switching between them', () => {
    const [client, site] = selectors();
    client.control.setValue({ $ref: 'c1' });
    fixture.detectChanges();
    site.control.setValue({ $ref: 's1' });
    fixture.detectChanges();

    state.contextScope.set('main');
    fixture.detectChanges();
    state.contextScope.set('admin');
    fixture.detectChanges();
    expect(state.contexts()['site']?.value).toEqual({ $ref: 's1' });
  });

  it('follows the context when it changes elsewhere', () => {
    state.setContext('client', ContextValue.fixed('client', { $ref: 'c9' }, 'client'));
    fixture.detectChanges();
    expect(selectors()[0].control.value).toEqual({ $ref: 'c9' });
  });
});
